import cv2, numpy as np
from PIL import Image
im=np.asarray(Image.open('first_frame.png').convert('RGB'))
# central highpass: examine difference from horizontal blur? save feature maps magnified
for kind in ['canny','laplacian','sat','bright']:
 if kind=='canny': x=cv2.Canny(cv2.cvtColor(im,cv2.COLOR_RGB2GRAY),15,50)
 elif kind=='laplacian': x=np.abs(cv2.Laplacian(cv2.cvtColor(im,cv2.COLOR_RGB2GRAY),cv2.CV_32F)); x=np.clip(x*3,0,255).astype(np.uint8)
 elif kind=='sat': x=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)[:,:,1]
 else: x=im.mean(2).astype(np.uint8)
 crop=x[0:80,115:185]
 Image.fromarray(crop).resize((560,640),Image.Resampling.NEAREST).save('.tmp/feature_'+kind+'.png')
PY"

